  (uuid_generate_v4(), 'navajo-pearl-handmade-4-5-and-8mm-necklace-german-silver-beads-choose-length', '4318682489', 'https://www.etsy.com/listing/4318682489/navajo-pearl-handmade-4-5-and-8mm?click_key=1cfeb984-505e-4dfb-bcde-81f75e423585%3ALTc6306ef0e08db6f17b60661e019df6cbaebb40b0&click_sum=034cd545&ls=s&ga_order=most_relevant&ga_search_type=all&ga_view_type=gallery&ga_search_query=Navajo+jewelry&ref=search_grid-23164-11-35&sr_prefetch=1&pf_from=search&frs=1&sts=1&content_source=1cfeb984-505e-4dfb-bcde-81f75e423585%253ALTc6306ef0e08db6f17b60661e019df6cbaebb40b0',
