  (uuid_generate_v4(), 'beautiful-new-navajo-tribe-earrings-by-tanya-benally-36-mojave-turquoise-stones-', '4452373585', 'https://www.etsy.com/listing/4452373585/beautiful-new-navajo-tribe-earrings-by?click_key=EugkcJZevM2EO6fM0v0nl1VJ0U96%3ALTdbdcfb724e322c23ea7c0da4e88f854b8dcc4633&click_sum=62f10de5&ls=a&ga_order=most_relevant&ga_search_type=all&ga_view_type=gallery&ga_search_query=Navajo+jewelry&ref=search_grid-23163-11-9&sr_prefetch=1&pf_from=search&frs=1&cns=1',
